const aid = (d: Diff, a: A, en: LangBlock, hi: LangBlock) => SE("assistive-aids", d, a, en, hi);
const CD = (topic: string, d: Diff, a: A, en: LangBlock, hi: LangBlock): PatwariQuestion => q(0, "pedagogy", topic, d, a, en, hi);
const HG = (topic: string, d: Diff, a: A, en: LangBlock, hi: LangBlock): PatwariQuestion => q(0, "hp-gk", topic, d, a, en, hi);
const GS = (topic: string, d: Diff, a: A, en: LangBlock, hi: LangBlock): PatwariQuestion => q(0, "general-studies", topic, d, a, en, hi);

